def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}}}

    change = new - old
    value = change / old * 100
    return {
        "value": value,
        "trace": {
            "old": old,
            "new": new,
            "change": change,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"},
        },
    }
